<?php
namespace Modules\Cutting\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Modules\Core\Models\ApprovalRequest;use Modules\Core\Models\Concerns\BelongsToCompany;use Modules\Core\Models\User;use Modules\MasterData\Models\Uom;use Modules\Receiving\Models\FabricRoll;
class ShadeOverrideRequest extends Model { use BelongsToCompany; protected $fillable=['company_id','lay_id','fabric_roll_id','uom_id','qty_used','reason','status','approval_request_id','requested_by','applied_by','applied_at']; protected function casts():array{return['qty_used'=>'decimal:4','applied_at'=>'datetime'];} public function lay():BelongsTo{return $this->belongsTo(Lay::class);} public function fabricRoll():BelongsTo{return $this->belongsTo(FabricRoll::class);} public function uom():BelongsTo{return $this->belongsTo(Uom::class);} public function approvalRequest():BelongsTo{return $this->belongsTo(ApprovalRequest::class);} public function requester():BelongsTo{return $this->belongsTo(User::class,'requested_by');} }
